function tick(){const now=new Date(),text=timeText();document.querySelectorAll('[data-live-time]').forEach(el=>el.textContent=text);document.querySelectorAll('[data-live-date]').forEach(el=>el.textContent=dateText());if(focusRunning){focusSeconds=Math.max(0,Math.ceil((focusEnd-Date.now())/1000));if(!focusSeconds){focusRunning=false;toast("Focus complete. Take a break.");const b=$('[data-v2="focus-toggle"]');if(b)b.textContent="Start Focus"}}const digits=homeTimerMode==='focus'?`${String(Math.floor(focusSeconds/60)).padStart(2,'0')}${String(focusSeconds%60).padStart(2,'0')}`:text.replace(':','');document.querySelectorAll('[data-digit]').forEach((el,i)=>{const v=digits[i];if(el.dataset.value!==v){const old=el.dataset.value||v;el.dataset.value=v;el.querySelector('.digit-value').textContent=v;const flap=el.querySelector('.digit-flap');flap.textContent=old;let lower=el.querySelector('.flip-old-bottom');if(!lower){lower=document.createElement('i');lower.className='flip-old-bottom';lower.setAttribute('aria-hidden','true');el.append(lower)}lower.textContent=old;el.querySelector('.digit-flap-bottom').textContent=v;el.classList.remove('flipping');void el.offsetWidth;el.classList.add('flipping')}});const field=$('#rain-field');if(field&&!document.hidden){const minute=text,second=String(now.getSeconds()).padStart(2,'0');if(lastRainMinute!==minute){if(lastRainMinute&&typeof dissolveRainCycle==='function')dissolveRainCycle();lastRainMinute=minute;const h=$('[data-rain-hour]'),m=$('[data-rain-minute]');updateRainPart(h,text.split(':')[0],'hour');updateRainPart(m,text.split(':')[1],'minute')}if(lastRainSecond!==second){lastRainSecond=second;const n=document.createElement('span');n.className='rain-drop';n.textContent=second;n.style.setProperty('--x',(8+((now.getSeconds()*37)%85))+'%');n.style.setProperty('--drift',((now.getSeconds()%5)-2)*11+'px');n.style.setProperty('--angle',((now.getSeconds()%7)-3)*7+'deg');field.append(n)}}}
let transitionUntil=0,upArmedAt=0,downArmedAt=0,gestureTotal=0,lastWheelAt=0,touchStart=null,wheelBurstHandled=false;
let homeCoverTransition=null;
// Snapshot the whole page, including fixed chrome and canvas themes. Only the
// home snapshot moves; the space snapshot stays full-size underneath it.
function transitionHomeCover(previous,next,update){
  if(homeCoverTransition){
    homeCoverTransition.cancelled=true;
    homeCoverTransition.animation.skipTransition();
    homeCoverTransition=null;
    delete document.documentElement.dataset.homeCover;
  }
  const paired=(previous==='home'&&next==='space')||(previous==='space'&&next==='home');
  const transitionOverlays=paired?[...document.querySelectorAll('#toast,.scroll-invitation')].map(node=>({node,hidden:node.hidden})):[];
  transitionOverlays.forEach(({node})=>{node.classList.remove('show');node.classList.add('navigation-transition');node.hidden=true});
  if(!paired||document.readyState==='loading'||!document.startViewTransition||matchMedia('(prefers-reduced-motion: reduce)').matches){update();transitionOverlays.forEach(({node,hidden})=>{node.hidden=hidden;node.classList.remove('navigation-transition')});return}
  const task={cancelled:false,animation:null};
  const cleanup=()=>{transitionOverlays.forEach(({node,hidden})=>{node.hidden=hidden;node.classList.remove('navigation-transition')});if(homeCoverTransition===task){homeCoverTransition=null;delete document.documentElement.dataset.homeCover}};
  homeCoverTransition=task;
  document.documentElement.dataset.homeCover=next==='space'?'leaving':'returning';
  try{
    task.animation=document.startViewTransition(()=>{if(!task.cancelled)update()});
    task.animation.ready.catch(()=>{});
    task.animation.finished.then(cleanup,cleanup);
  }catch{
    cleanup();update();
  }
}
window.addEventListener('resize',()=>homeCoverTransition?.animation?.skipTransition());
function changeView(next){if(view===next||Date.now()<transitionUntil)return;const previous=view;view=next;transitionUntil=Date.now()+1250;upArmedAt=0;downArmedAt=0;gestureTotal=0;transitionHomeCover(previous,next,()=>{render();window.scrollTo({top:0,behavior:'instant'})})}
function navigationGesture(delta){if(Date.now()<transitionUntil)return;const doc=document.documentElement,now=Date.now();if(view==='home'&&delta>0&&window.scrollY+innerHeight>=doc.scrollHeight-8){if(prefs.homeEntryGesture==='click')return;if(downArmedAt&&now-downArmedAt<2400){changeView('space');return}downArmedAt=now;toast("Scroll down again to open your space",'bottom');return}if(view==='space'&&delta<0&&window.scrollY<=2){if(upArmedAt&&now-upArmedAt>350&&now-upArmedAt<2600)changeView('home');else{upArmedAt=now;toast("Scroll up again to go home",'bottom')}}}
document.addEventListener('click',e=>{if(e.target.closest('[data-pref="homeEntryGesture"]')){downArmedAt=0;gestureTotal=0;wheelBurstHandled=false}});
window.addEventListener('wheel',e=>{if(document.querySelector('dialog[open]')||e.ctrlKey||Math.abs(e.deltaX)>Math.abs(e.deltaY)||e.target.closest('input,select,textarea,.results,.dock-options,.sidebar,.group-tabs'))return;const now=Date.now(),gap=now-lastWheelAt;lastWheelAt=now;if(gap>160){gestureTotal=0;wheelBurstHandled=false}gestureTotal+=e.deltaY*(e.deltaMode===1?16:1);const boundary=view==='home'?window.scrollY+innerHeight>=document.documentElement.scrollHeight-8:window.scrollY<=2;if(boundary&&((view==='home'&&e.deltaY>0)||(view==='space'&&e.deltaY<0))){e.preventDefault();if(Math.abs(gestureTotal)>65&&!wheelBurstHandled){navigationGesture(gestureTotal);wheelBurstHandled=true;gestureTotal=0}}},{passive:false});
window.addEventListener('touchstart',e=>{if(e.touches.length===1&&!document.querySelector('dialog[open]')&&!e.target.closest('input,select,button,a,.results,.sidebar,.group-tabs'))touchStart={y:e.touches[0].clientY,top:scrollY};else touchStart=null},{passive:true});
