function quickSearch(){let dialog=$('#quick-search');if(!dialog){dialog=document.createElement('dialog');dialog.id='quick-search';dialog.addEventListener('close',()=>{if(!dialog.open)dialog.replaceChildren()});document.body.append(dialog)}dialog.innerHTML=`<div class="dialog-heading"><h2>Explore</h2><button class="icon-button" data-action="close" aria-label="Close Search">×</button></div>${searchMarkup(true)}${standardAI()}`;if(!dialog.open)dialog.showModal();const form=dialog.querySelector('#search-form'),input=dialog.querySelector('#search-input');form.onsubmit=submitSearch;input.oninput=e=>{if(searchType==='saved')savedSearch(e.currentTarget.closest('.search-area'))};input.focus()}
