function toggleMute(){muted=!muted;if(audioMaster)audioMaster.gain.setTargetAtTime(muted?0:.45,audioCtx.currentTime,.04);syncMusicUI()}
function syncMusicUI(){const play=$('[data-v3="audio-play"]');if(!play)return;play.textContent=playing?'Ⅱ':'▶';play.setAttribute('aria-label',playing?"Pause Music":"Play Music");play.setAttribute('aria-pressed',String(playing));$('.vinyl')?.classList.toggle('spinning',playing);$('.tonearm')?.classList.toggle('engaged',playing);$('.equalizer')?.classList.toggle('moving',playing&&!muted);const mute=$('[data-v3="audio-mute"]');mute.innerHTML=muted?"Mute <span>×</span>":"Sound <span>♪</span>";mute.setAttribute('aria-label',muted?"Unmute":"Mute");mute.setAttribute('aria-pressed',String(muted));$('#track-select').value=String(trackIndex);$('.player-caption').textContent=`${TRACKS[trackIndex].mood} · ${playing?(muted?"Muted":"Playing"):"Play"} · Original music`;}
function musicComposition(){return `<div class="music-composition"><div class="record-sleeve"><div class="vinyl ${playing?'spinning':''}"><div class="vinyl-label"><span>SIDE A</span><b>Now</b><small>THE SOUND OF TODAY</small><i class="spindle"></i></div></div><div class="tonearm ${playing?'engaged':''}" aria-hidden="true"><span class="arm-pivot"></span><span class="arm-shaft"></span><span class="arm-head"></span></div><span class="record-calibration" aria-hidden="true">33⅓ &nbsp; • &nbsp; STEREO</span></div><div class="music-info"><div class="eyebrow">THE SOUND OF YOUR DAY</div><h1>Tune in,<br>find your rhythm.</h1><div class="music-time" data-live-time>${timeText()}</div><div class="music-date" data-live-date>${dateText()}</div><div class="play-progress"><span id="music-progress"></span></div><div class="player-controls"><button class="play-toggle" data-v3="audio-play" aria-label="${playing?"Pause Music":"Play Music"}">${playing?'Ⅱ':'▶'}</button><select id="track-select" aria-label="Choose Music">${TRACKS.map((t,i)=>`<option value="${i}" ${i===trackIndex?'selected':''}>${t.name} · ${t.mood}</option>`).join('')}</select><button class="mute-control" data-v3="audio-mute" aria-label="${muted?"Unmute":"Mute"}">${muted?"Mute ×":"Sound ♪"}</button><span class="equalizer ${playing&&!muted?'moving':''}" aria-hidden="true"><i></i><i></i><i></i><i></i></span></div><span class="player-caption">${TRACKS[trackIndex].mood} · ${playing?(muted?"Muted":"Playing"):"Play"} · Original music</span></div></div>`}

const PLANETS=[{id:'violet',name:"Violet Star",color:'#aaa0c9',shadow:'#22263e',size:40},{id:'ocean',name:"Ocean Star",color:'#83adb6',shadow:'#193b4c',size:44},{id:'sand',name:"Golden Star",color:'#b8a387',shadow:'#554537',size:37},{id:'moss',name:"Jade Star",color:'#8fa993',shadow:'#2c443e',size:31},{id:'rose',name:"Red Star",color:'#b6867c',shadow:'#4d2e38',size:35},{id:'moon',name:"Lunar Star",color:'#bfc5c4',shadow:'#434b56',size:26}];
let centerPlanet='violet',orbitFrameId=0,orbitPositions={},orbitRefresh=null;
function cosmosComposition(){return `<div class="cosmos-composition"><div class="orbit-system" role="group" aria-label="Click a planet to center it"><div class="orbit o1"></div><div class="orbit o2"></div>${PLANETS.map(p=>`<button class="orbit-body" data-planet="${p.id}" style="--planet-light:${p.color};--planet-shadow:${p.shadow}" aria-label="${p.name}${p.id===centerPlanet?", centered":", center this"}" aria-pressed="${p.id===centerPlanet}"><span class="planet-surface"></span><span class="planet-name">${p.name}</span></button>`).join('')}<span class="orbit-hint">Center Planet</span></div><div class="cosmos-copy"><span class="eyebrow">PERSONAL OBSERVATORY</span><h1>Explore the cosmos,<br>find yourself.</h1><div class="cosmos-time" data-live-time>${timeText()}</div><span class="cosmos-date" data-live-date>${dateText()}</span></div><span class="coordinates">LOCAL TIME<br>EARTH · SOLAR SYSTEM<br>A little corner of the universe, yours.</span></div>`}
function startOrbits(){cancelAnimationFrame(orbitFrameId);const container=$('.orbit-system');if(!container)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let last=performance.now();function frame(now){if(!container.isConnected)return;const blend=reduced?1:1-Math.exp(-Math.min(60,now-last)/145);last=now;const others=PLANETS.filter(p=>p.id!==centerPlanet);PLANETS.forEach(p=>{const el=container.querySelector(`[data-planet=${p.id}]`),central=p.id===centerPlanet,index=others.indexOf(p),angle=(reduced?0:now/1000)*(0.07+index*.011)+index*1.23,rx=190+index*13,ry=95+index*10,rotation=-.42;const xx=Math.cos(angle)*rx,yy=Math.sin(angle)*ry;const target={x:central?307.5:307.5+xx*Math.cos(rotation)-yy*Math.sin(rotation),y:central?242.5:242.5+xx*Math.sin(rotation)+yy*Math.cos(rotation),size:central?275:p.size};const pos=orbitPositions[p.id]??={...target};for(const k of ['x','y','size'])pos[k]+=(target[k]-pos[k])*blend;el.style.width=pos.size+'px';el.style.height=pos.size+'px';el.style.transform=`translate(${pos.x-pos.size/2}px,${pos.y-pos.size/2}px)`;el.style.zIndex=central?'4':(Math.sin(angle)>.15?'6':'2');el.classList.toggle('is-center',central);el.setAttribute('aria-pressed',String(central));el.setAttribute('aria-label',`${p.name}${central?", centered":", center this"}`)});if(!reduced)orbitFrameId=requestAnimationFrame(frame)}orbitRefresh=()=>frame(performance.now());orbitRefresh()}

let rainPrevious={hour:null,minute:null};
function updateRainPart(el,value,key){if(!el)return;const previous=rainPrevious[key],changed=previous!==value;rainPrevious[key]=value;if(!changed){if(!el.querySelector('.rain-value'))el.innerHTML=`<span class="rain-value">${value}</span>`;return}el.innerHTML=`<span class="rain-value">${value}</span>`;el.setAttribute('aria-label',`${key==='hour'?"Hours":"Minutes"} ${value}`);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const incoming=el.querySelector('.rain-value');incoming.animate([{transform:'translateY(-420px)',opacity:0},{transform:'translateY(-60px)',opacity:1,offset:.62},{transform:'translateY(7px)',opacity:1,offset:.84},{transform:'translateY(0)',opacity:1}],{duration:1000,easing:'cubic-bezier(.38,.02,.68,1)'});if(previous!==null){const old=document.createElement('span');old.className='rain-old';old.textContent=previous;old.setAttribute('aria-hidden','true');el.append(old);const animation=old.animate([{transform:'translateY(0) scale(1)',opacity:1},{transform:'translateY(0) scale(1)',opacity:1,offset:.68},{transform:'translateY(55px) scale(.7,.2)',opacity:0}],{duration:1000,easing:'ease-in',fill:'forwards'});animation.onfinish=()=>old.remove()}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.v3==='audio-play')toggleMusic();if(b.dataset.v3==='audio-mute')toggleMute();if(b.dataset.planet&&centerPlanet!==b.dataset.planet){centerPlanet=b.dataset.planet;if(matchMedia('(prefers-reduced-motion: reduce)').matches)orbitRefresh?.()}});
document.addEventListener('change',e=>{if(e.target.id==='track-select')chooseTrack(Number(e.target.value))});
window.addEventListener('pagehide',()=>{clearInterval(audioLoop);audioCtx?.close();cancelAnimationFrame(orbitFrameId)});

// Render the core cover before the enhancement bundles load. This keeps a slow
// or interrupted enhancement script from leaving the initial shell empty.
render();
